where slug in ('m-collection-s741','d-reread-before-rebuilt-plan-s741','d-shared-reader-change-reader-on-fable-s741','d-crc-filing-parked-for-moved-pdf-s741','p-noncredit-test-injected-key-collides-with-live-save-s741','p-conductor-apply-from-detached-head-s741','p-migrate-queue-global-pending-cancels-s741','f-ela-committed-passes-live-older-s741','f-keep-better-major-equal-rank-s741')
